package com.dudleylane.quickfix.fix41;

/** FIX 4.1 Quote (35=S). Generated by spec/GeneratorJava.rb. */
public class Quote extends Message {
    public static final String MSGTYPE = "S";

    public Quote() {
        getHeader().setField(35, MSGTYPE);
    }

    private Quote(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a Quote, without copying it: the same engine object, so valid only while message is. A
     * callback's message is the engine's and lasts only for the callback; copy it (new Message(message)) to keep it.
     */
    public static Quote view(com.dudleylane.quickfix.Message message) {
        if (!MSGTYPE.equals(message.getHeader().getField(35))) {
            throw new IllegalArgumentException("not a Quote (35=" + MSGTYPE + "): 35=" + message.getHeader().getField(35));
        }
        return new Quote(getCPtr(message));
    }
}
